INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(301, 'Genesis 12:6', 'Genesis', 12, 6, '&nbsp;ابرام په دې مُلک کښې سفر کولو چې شِکم ته نزدې، د موره پاکې ونې زيارت له راغلو. (په هغه وخت کښې کنعانيان لا په دې مُلک کښې اوسېدل.)', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(302, 'Genesis 12:7', 'Genesis', 12, 7, '&nbsp;نو مالِک خُدائ ابرام ته څرګند شو او هغۀ ته يې وفرمائيل، ”دا هغه مُلک دے چې زۀ يې ستا اولاد له ورکوم.“ بيا ابرام هلته مالِک خُدائ ته يوه قربان‌ګاه جوړه کړه، چرته چې ورته راڅرګند شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(303, 'Genesis 12:8', 'Genesis', 12, 8, '&nbsp;د دې نه پس، هغۀ د بيت‌ايل ښار نمرخاتۀ طرف ته د غرونو مُلک ته کَډه يوړه او هغۀ په هغه ځائ کښې چې نمرپرېواتۀ طرف ته بيت‌ايل او نمرخاتۀ ته عى دے په مينځ کښې خېمه ولګوله. هلته يې هم يوه قربان‌ګاه جوړه کړه او د مالِک خُدائ نوم يې پرې واخستو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(304, 'Genesis 12:9', 'Genesis', 12, 9, '&nbsp;بيا هغۀ جدا جدا ځايونو ته هِجرت کولو چې د کنعان جنوبى حِصې ته راغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(305, 'Genesis 12:10', 'Genesis', 12, 10, '&nbsp;او يو ځل په کنعان کښې قحط راغلو او دا د برداشت نه دومره بهر وو چې ابرام مِصر ته هِجرت وکړو، چې هلته دېره شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(306, 'Genesis 12:11', 'Genesis', 12, 11, '&nbsp;چې کله هغه تقريباً مِصر ته اوړېدو، هغۀ خپلې ښځې سارۍ ته وفرمائيل، ”دا خبره واوره، ما ته پته ده چې تۀ ښائسته يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(307, 'Genesis 12:12', 'Genesis', 12, 12, '&nbsp;کۀ د مِصر خلق تا وګورى، نو هغوئ به ګُمان وکړى چې تۀ زما ښځه يې، نو هغوئ به ما مړ کړى او تا به ژوندۍ پرېږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(308, 'Genesis 12:13', 'Genesis', 12, 13, '&nbsp;هغوئ ته ووايه چې زۀ يې خور يم، نو داسې به ما ته څۀ نۀ وائى او ستا په وجه به زۀ ژوندے پاتې شم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(309, 'Genesis 12:14', 'Genesis', 12, 14, '&nbsp;چې کله هغوئ مِصر ته واوړېدل، نو مِصريانو هغه وليده چې ډېره ښائسته ښځه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(310, 'Genesis 12:15', 'Genesis', 12, 15, '&nbsp;نو د فِرعون درباريانو هغه وليده او فِرعون ته يې ووئيل چې هغه څومره ښائسته وه، نو هغه يې محل ته بوتله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(311, 'Genesis 12:16', 'Genesis', 12, 16, '&nbsp;د هغې په وجه فِرعون د ابرام ښۀ عزت وکړو او هغۀ له يې د ګډو او چېلو رَمې ورکړې. څاروى، خرۀ، اوښان او ښځې او نران خِدمتګاران يې هم ورکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(312, 'Genesis 12:17', 'Genesis', 12, 17, '&nbsp;خو فِرعون سارۍ بوتلې وه، نو ځکه مالِک خُدائ په فِرعون او د هغۀ په درباريانو يوه لويه وبا راوسته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(313, 'Genesis 12:18', 'Genesis', 12, 18, '&nbsp;فِرعون ابرام راوغوښتو او تپوس يې ترې وکړو، ”دا تا زما سره څۀ کړى دى؟ تا ولې ما ته ونۀ وئيل چې هغه ستا ښځه ده؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(314, 'Genesis 12:19', 'Genesis', 12, 19, '&nbsp;تا ولې ووئيل چې هغه ستا خور ده او ما درنه بوتله چې ښځه يې کړم؟ خپله ښځه د ځان سره بوځه او په خپله مخه ځه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(315, 'Genesis 12:20', 'Genesis', 12, 20, '&nbsp;فِرعون نوکرانو ته حُکم وکړو، نو هغوئ ابرام بوتلو او د خپلې ښځې او ټول مال سره يې د هغه مُلک نه بهر کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(316, 'Genesis 13:1', 'Genesis', 13, 1, '&nbsp;ابرام د خپلې ښځې سره او ټول مال سره د مِصر نه د کنعان په طرف صحرا ته لاړو او لوط هم ورسره وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(317, 'Genesis 13:2', 'Genesis', 13, 2, '&nbsp;ابرام ډېر مالداره سړے وو، د هغۀ څاروى وُو او د سپينو او سرو زرو مالِک هم وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(318, 'Genesis 13:3', 'Genesis', 13, 3, '&nbsp;او هغۀ جدا جدا ځايونو ته هِجرت کولو او بيت‌ايل ته روان وو. هغه هم هغه ځائ ته ورسېدو چې د بيت‌ايل او عى په مينځ کښې دے چرته چې هغه مخکښې دېره شوے وو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(319, 'Genesis 13:4', 'Genesis', 13, 4, '&nbsp;او قربان‌ګاه يې جوړه کړې وه. او د مالِک خُدائ نوم يې پرې اخستے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(320, 'Genesis 13:5', 'Genesis', 13, 5, '&nbsp;د لوط سره هم څاروى او رَمې وې، خپل خاندان او نوکران هم ورسره وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(321, 'Genesis 13:6', 'Genesis', 13, 6, '&nbsp;خو هلته دومره شنه زمکه نۀ وه چې دوئ دواړه په کښې يو ځائ پاتې شوى وے، ځکه چې د دوئ سره ډېر زيات مال وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(322, 'Genesis 13:7', 'Genesis', 13, 7, '&nbsp;نو د ابرام او د لوط د شپونکو په مينځ کښې جنګ وشو. (په هغه وخت کښې کنعانيان او فرزيان هم په هغه مُلک کښې اوسېدل.)', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(323, 'Genesis 13:8', 'Genesis', 13, 8, '&nbsp;نو ابرام لوط ته وفرمائيل، ”خُدائ پاک دې زما او ستا او زمونږ د شپونکو په مينځ کښې لانجه نۀ راولى، ځکه چې مونږ خپلوان يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(324, 'Genesis 13:9', 'Genesis', 13, 9, '&nbsp;ولې دا ټوله زمکه ستا په وړاندې نۀ ده؟ زما نه جدا شه. چې چرته دې خوښه وى هم هلته لاړ شه. کۀ تۀ ښى طرف ته ځې نو زۀ به ګس طرف ته ځم، کۀ تۀ ګس طرف ته ځې نو زۀ به ښى طرف ته لاړ شم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(325, 'Genesis 13:10', 'Genesis', 13, 10, '&nbsp;لوط سترګې واړولې راواړولې او د اُردن ټول هوار مېدان يې وليدو، چې د ضُعر پورې، د مالِک خُدائ د باغ په شان يا د مِصر د مُلک په شان ښې ډېرې اوبۀ يې لرلې. (په هغه وخت کښې مالِک خُدائ د سدوم او عموره ښارونه لا تباه کړى نۀ وُو.)', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(326, 'Genesis 13:11', 'Genesis', 13, 11, '&nbsp;نو لوط د ځان دپاره د اُردن ټول هوار مېدان خوښ کړو او نمرخاتۀ طرف ته لاړو. نو داسې دوئ دواړه جدا شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(327, 'Genesis 13:12', 'Genesis', 13, 12, '&nbsp;ابرام د کنعان په مُلک کښې پاتې شو او لوط په مېدان کښې د ښارونو په مينځ کښې دېره شو او سدوم سره نزدې يې خېمې ولګولې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(328, 'Genesis 13:13', 'Genesis', 13, 13, '&nbsp;چې د هغه ځائ خلق ډېر خراب او ګناهګار وُو او د مالِک خُدائ خلاف وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(329, 'Genesis 13:14', 'Genesis', 13, 14, '&nbsp;د لوط د تلو نه پس، مالِک خُدائ ابرام ته وفرمائيل، ”چرته چې تۀ ولاړ يې، د دې ځائ نه هر طرف ته ښۀ په غور سره وګوره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(330, 'Genesis 13:15', 'Genesis', 13, 15, '&nbsp;چې څومره زمکه ستا په نظر راځى، دا زۀ تا او ستا اولاد له همېشه دپاره درکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(331, 'Genesis 13:16', 'Genesis', 13, 16, '&nbsp;زۀ به تا له دومره ډېر اولاد درکوم چې هيڅ څوک به يې شمېرلے نۀ شى خو د خاورو د ذرو شمېرل به ترې آسان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(332, 'Genesis 13:17', 'Genesis', 13, 17, '&nbsp;پاڅه، روان شه او په ټوله زمکه نظر واچوه، ځکه چې دا ټوله تا له درکوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(333, 'Genesis 13:18', 'Genesis', 13, 18, '&nbsp;نو ابرام د دې ځائ نه کَډه واخستله او د ممرې پاکو ونو ته نزدې دېره شو، چې دا په حبرون کښې دے، او هلته يې مالِک خُدائ ته يوه قربان‌ګاه جوړه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(334, 'Genesis 14:1', 'Genesis', 14, 1, '&nbsp;په هغه وخت کښې، څلورو بادشاهانو، د بابل امرافِل، د الاسر اريوک، د عيلام کِدرلاعُمر او د جوئيم تِدعال،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(335, 'Genesis 14:2', 'Genesis', 14, 2, '&nbsp;د پينځو نورو بادشاهانو سره جنګ وکړو چې هغوئ دا دى، د سدوم بَرع، د عموره برشع، د ادمه سِنى‌اب، د ضبوئيم شِميبر او بالع يعنې د ضُعر بادشاه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(336, 'Genesis 14:3', 'Genesis', 14, 3, '&nbsp;دې پينځو بادشاهانو د سِديم په مېدان کښې اتفاق وکړو او لښکر يې جوړ کړو، چرته چې د مالګې درياب دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(337, 'Genesis 14:4', 'Genesis', 14, 4, '&nbsp;دوئ دولس کاله د کِدرلاعُمر د مشرۍ لاندې وُو، خو په ديارلسم کال هغوئ د هغۀ خِلاف بغاوت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(338, 'Genesis 14:5', 'Genesis', 14, 5, '&nbsp;يو کال وروستو کِدرلاعُمر او د هغۀ ملګرى د خپلو لښکرو سره راغلل او رفائيم ته يې په عستارات قرنيم کښې، زوزيم ته په حام کښې او ايميم ته د سِوى قِريَتائم په مېدان کښې شکست ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(339, 'Genesis 14:6', 'Genesis', 14, 6, '&nbsp;او حوريانو ته يې د ادوم په غرونو کښې شکست ورکړو او د صحرا په غاړه د اېل‌فاران پورې ورپسې روان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(340, 'Genesis 14:7', 'Genesis', 14, 7, '&nbsp;بيا دوئ ترې راوګرځېدل او قادِس ته واپس راغلل (چې بيا په عين مِصفات مشهور شو). دوئ د عماليقيانو ټول مُلک ونيوو او اموريانو له يې شکست ورکړو چې په حصيصون تامار کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(341, 'Genesis 14:8', 'Genesis', 14, 8, '&nbsp;د سدوم، عموره، ادمه، ضبوئيم او د بالع بادشاهان د قلعو نه راووتل او خپلې لښکرې يې د جنګ دپاره تيارې کړې او د سِديم په مېدان کښې يې جنګ وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(342, 'Genesis 14:9', 'Genesis', 14, 9, '&nbsp;پينځۀ بادشاهان، د څلورو بادشاهانو سره وجنګېدل چې دوئ د عيلام، د جوئيم، د بابل او د الاسر وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(343, 'Genesis 14:10', 'Genesis', 14, 10, '&nbsp;مېدان ټول د تارکولو د کندو نه ډک وو او چې کله د سدوم او عموره بادشاهان د جنګ نه تښتېدل، نو هغوئ په کندو کښې پرېوتل، خو هغه نور درې بادشاهان غرونو ته وتښتېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(344, 'Genesis 14:11', 'Genesis', 14, 11, '&nbsp;دې څلورو بادشاهانو چې په سدوم او عموره کښې څومره مال وو هغه يې ټول واخستو، چې په کښې د خوراک سامان هم وو او دوئ لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(345, 'Genesis 14:12', 'Genesis', 14, 12, '&nbsp;د ابرام ورارۀ لوط، په سدوم کښې اوسېدو، نو هغه يې هم بوتلو او هر څۀ يې ترې واخستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(346, 'Genesis 14:13', 'Genesis', 14, 13, '&nbsp;خو يو سړے وتښتېدو او ابرام، عبرانى ته يې دا هر څۀ ووئيل، چې هغه د ممرې، امورى پاکو ونو ته نزدې اوسېدو، ممرې او د هغۀ خپلوانو اسکال او عانير هم د ابرام په جنګ کښې ملګرتيا کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(347, 'Genesis 14:14', 'Genesis', 14, 14, '&nbsp;چې کله ابرام خبر شو چې د هغۀ ورارۀ نيولے شوے دے، هغۀ خپل ټول درې سوه اتلس فوجيان خپلې خېمې ته راوغوښتل او په هغه څلورو بادشاهانو پسې تر دان پورې روان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(348, 'Genesis 14:15', 'Genesis', 14, 15, '&nbsp;هلته هغۀ فوجيان په ډلو کښې تقسيم کړل او د شپې يې په دشمن حمله وکړه او هغوئ له يې شکست ورکړو، هغه د دمشق شمالى طرف ته تر حوبه پورې په هغوئ پسې وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(349, 'Genesis 14:16', 'Genesis', 14, 16, '&nbsp;او چې کوم مال يې تښتولے وو هغه يې ترې واپس واخستلو. او خپل ورارۀ لوط يې سره د ټول مال واپس راوستو او چې کومې ښځې او کسان نيولے شوى وُو هغه يې هم راوستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(350, 'Genesis 14:17', 'Genesis', 14, 17, '&nbsp;چې کله ابرام په کِدرلاعُمر او په نورو بادشاهانو د فتح موندلو نه پس واپس راغلو، نو د سدوم بادشاه د سِوى مېدان ته ورله ستړى مشى له راغلو (چې بل نوم يې د بادشاهانو مېدان دے).', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(351, 'Genesis 14:18', 'Genesis', 14, 18, '&nbsp;او مَلِک‌صِدق، چې د شاليم بادشاه او د خُدائ تعالىٰ يو اِمام وو، ابرام له روټۍ او مے راوړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(352, 'Genesis 14:19', 'Genesis', 14, 19, '&nbsp;هغۀ دپاره يې برکت وغوښتو او ورته يې وفرمائيل، ”خُدائ تعالىٰ دې ابرام له برکت ورکړى، چا چې آسمان او زمکه پېدا کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(353, 'Genesis 14:20', 'Genesis', 14, 20, '&nbsp;ټول ثناء صِفت دې د هغه خُدائ تعالىٰ وى چې ستا دشمنان يې ستا د پښو لاندې کړل.“ نو ابرام مَلِک‌صِدق ته د ټول مالِ غنيمت نه لسمه حِصه ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(354, 'Genesis 14:21', 'Genesis', 14, 21, '&nbsp;د سدوم بادشاه ابرام ته ووئيل، ”دا ټول مال ستا شو، خو ما له زما ټول خلق واپس راکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(355, 'Genesis 14:22', 'Genesis', 14, 22, '&nbsp;ابرام جواب ورکړو، ”زما دې په مالِک خُدائ قسم وى، چې ډېر لوئ خُدائ تعالىٰ دے، چې د آسمان او زمکې پېدا کوونکے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(356, 'Genesis 14:23', 'Genesis', 14, 23, '&nbsp;چې زۀ به ستاسو هيڅ څيز نۀ استعمالوم، يو تار يا د څپلۍ تسمه قدر به هم ستاسو نۀ وړم. چې تاسو دا ونۀ وايئ، چې ابرام زمونږ په مال مالداره شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(357, 'Genesis 14:24', 'Genesis', 14, 24, '&nbsp;زۀ به ستاسو نه د هغه مال نه بغېر يو څيز هم نۀ قبلوم کوم چې زما کسانو استعمال کړے دے. خو زما ملګرى، عانير، اسکال او ممرې دې خپله حِصه ترې نه واخلى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(358, 'Genesis 15:1', 'Genesis', 15, 1, '&nbsp;څۀ موده پس، د مالِک خُدائ کلام ابرام ته په رويا کښې نازل شو چې، ”ابرامه، يرېږه مه. زۀ ستا ډال يم او زۀ به تا له يو لوئ اِنعام درکوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(359, 'Genesis 15:2', 'Genesis', 15, 2, '&nbsp;خو ابرام جواب ورکړو، ”مالِکه، مالِکه خُدايه، ستا اِنعام به ما له څۀ فائده راکړى؟ زما خو خپل بچى هم نشته او دغه د دمشق اِلى‌عزر زما وارث دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(360, 'Genesis 15:3', 'Genesis', 15, 3, '&nbsp;ګوره، تا ما له اولاد نۀ دے راکړے او زما غلام به زما ميراث اخلى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(361, 'Genesis 15:4', 'Genesis', 15, 4, '&nbsp;نو د مالِک خُدائ کلام يو ځل بيا په هغۀ نازل شو چې، ”ستا غلام اِلى‌عزر به ستا ميراث نۀ اخلى، ستا خپل زوئ به ستا وارث وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(362, 'Genesis 15:5', 'Genesis', 15, 5, '&nbsp;مالِک خُدائ هغه بهر بوتلو او ورته يې وفرمائيل، ”آسمان ته وګوره، کۀ تۀ د آسمان ستورى شمېرلے شې نو وې شمېره، ستا اولاد به د ستورو په شان ډېر وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(363, 'Genesis 15:6', 'Genesis', 15, 6, '&nbsp;ابرام په مالِک خُدائ ايمان راوړو او دا د هغۀ دپاره په صداقت حساب شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(364, 'Genesis 15:7', 'Genesis', 15, 7, '&nbsp;بيا مالِک خُدائ هغۀ ته وفرمائيل، ”زۀ مالِک خُدائ يم، چا چې په بابل کښې د اُور نه راوويستلې، چې دا زمکه ستا خپله شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(365, 'Genesis 15:8', 'Genesis', 15, 8, '&nbsp;خو ابرام ترې تپوس وکړو، ”مالِکه، مالِکه خُدايه، ما ته به څنګه پته ولګى چې دا به زما شى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(366, 'Genesis 15:9', 'Genesis', 15, 9, '&nbsp;هغۀ جواب ورکړو، ”ما له يوه سخۍ، يوه چېلۍ او يو ګډ راوله، چې هر يو د درېو کالو وى او يوه ګوګوشتکه او کونتره هم راوړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(367, 'Genesis 15:10', 'Genesis', 15, 10, '&nbsp;ابرام دا ځناور حاضر کړل، حلال يې کړل، هغه درې څاروى يې په مينځ نيم کړل او په دوه قطارونو کښې يې نيم نيم يو بل ته مخامخ کېښودل، خو مارغان يې په مينځ نيم نۀ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
