(374, 'Genesis 15:17', 'Genesis', 15, 17, '&nbsp;چې کله نمر پرېوتو او توره تيارۀ شوه، نو يو د بلو سکارو لوښے چې لوګے يې کولو او يو بَل لرګے ناڅاپى راڅرګند شو او د ځناورو په مينځ کښې تېر شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(375, 'Genesis 15:18', 'Genesis', 15, 18, '&nbsp;نو په هغه وخت کښې مالِک خُدائ د ابرام سره يو لوظ وکړو. هغۀ وفرمائيل، ”زۀ تا سره دا لوظ کوم چې زۀ به ستا اولاد له د مِصر د دې سيند نه د فرات تر لوئ سيند پورې دا زمکه ورکوم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(376, 'Genesis 15:19', 'Genesis', 15, 19, '&nbsp;او ورسره د قينيانو مُلک، د قنزيانو، د قدمونيانو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(377, 'Genesis 15:20', 'Genesis', 15, 20, '&nbsp;د حِتيانو، د فرزيانو، د رفائيم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(378, 'Genesis 15:21', 'Genesis', 15, 21, '&nbsp;د اموريانو، د کنعانيانو، د جرجاسيانو او د يبوسيانو مُلک هم ورکوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(379, 'Genesis 16:1', 'Genesis', 16, 1, '&nbsp;د ابرام د ښځې سارۍ تر اوسه پورې بچى نۀ وُو شوى. خو د هغې يوه مِصرۍ وينځه وه چې نوم يې هاجِره وه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(380, 'Genesis 16:2', 'Genesis', 16, 2, '&nbsp;نو هغې ابرام ته ووئيل، ”مالِک خُدائ ما له اولاد نۀ دے راکړے. تۀ ولې زما د وينځې سره شپه نۀ تېروې؟ کېدے شى چې زۀ د هغې نه آباده شم.“ نو ابرام د سارۍ خبره ومنله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
