(397, 'Genesis 17:3', 'Genesis', 17, 3, '&nbsp;ابرام مخ په زمکه ولګولو، سجده يې وکړه او خُدائ پاک وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(398, 'Genesis 17:4', 'Genesis', 17, 4, '&nbsp;”ګوره، زۀ تا سره دا لوظ کوم، زۀ دا لوظ کوم چې تۀ به د ډېرو قومونو پلار شې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(399, 'Genesis 17:5', 'Genesis', 17, 5, '&nbsp;نور به تا ته ابرام نۀ شى وئيلے، ستا نوم اِبراهيم شو، ځکه چې زۀ تا د ډېرو قومونو پلار جوړوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(400, 'Genesis 17:6', 'Genesis', 17, 6, '&nbsp;زۀ به تا ډېر زيات آباد کړم، او ستا نه به قومونه جوړ کړم او ستا په اولاد کښې به بادشاهان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');